//! Cargo-driven `reactos.exe` link, generated by tools/cargo_cell_gen.py
//! from the cmake link it replaces.
//! The body is reactos-rust; reactos-link builds the PE.

use reactos_link::{Linker, ModuleKind, MsvcrtexKind};
use std::env;

fn main() {
    let arch = env::var("CARGO_CFG_TARGET_ARCH").expect("CARGO_CFG_TARGET_ARCH");
    let (target_json, entry) = match arch.as_str() {
        "x86" => ("i686-pc-windows-gnu", "_wWinMainCRTStartup"),
        "x86_64" => ("x86_64-pc-windows-gnu", "wWinMainCRTStartup"),
        "aarch64" => ("aarch64-pc-windows-gnullvm", "wWinMainCRTStartup"),
        o => panic!("reactos-cargo: unsupported arch {o}"),
    };

    let link_order: &[&str] = match arch.as_str() {
        "x86" => &["body", "engine:uuid", "engine:c:zlib_solo", "import:setuplib", "import:advapi32", "import:gdi32", "import:user32", "import:comctl32", "import:shlwapi", "import:setupapi", "import:msvcrt", "import:kernel32", "import:ntdll", "engine:delayimp_rust", "engine:oldnames"],
        "x86_64" => &["body", "engine:uuid", "engine:c:zlib_solo", "import:setuplib", "import:advapi32", "import:gdi32", "import:user32", "import:comctl32", "import:shlwapi", "import:setupapi", "import:msvcrt", "import:kernel32", "import:ntdll", "engine:delayimp_rust", "engine:oldnames"],
        "aarch64" => &["body", "engine:uuid", "engine:c:zlib_solo", "import:setuplib", "import:advapi32", "import:gdi32", "import:user32", "import:comctl32", "import:shlwapi", "import:setupapi", "import:msvcrt", "import:kernel32", "import:ntdll", "engine:delayimp_rust", "engine:oldnames"],
        _ => unreachable!(),
    };

    Linker::new(target_json)
        .rust_staticlib("reactos-rust")
        .c_from_compile_db("reactos_shims", &["base/setup/reactos/rust_varargs_shim.c", "vendor/treelist/treelist.c"])
        .resource_from_rc("base/setup/reactos/reactos.rc", "reactos_res")
        .delay_import_lib("base/setup/lib/setuplib.spec", "setuplib.dll", "setuplib")
        .import_lib("dll/win32/advapi32/advapi32.spec", "advapi32.dll", "advapi32")
        .import_lib("win32ss/gdi/gdi32/gdi32.spec", "gdi32.dll", "gdi32")
        .import_lib("win32ss/user/user32/user32.spec", "user32.dll", "user32")
        .import_lib("dll/win32/comctl32/comctl32.spec", "comctl32.dll", "comctl32")
        .import_lib("dll/win32/shlwapi/shlwapi.spec", "shlwapi.dll", "shlwapi")
        .import_lib("dll/win32/setupapi/setupapi.spec", "setupapi.dll", "setupapi")
        .import_lib("dll/win32/msvcrt/msvcrt.spec", "msvcrt.dll", "msvcrt")
        .import_lib("dll/win32/kernel32/kernel32.spec", "kernel32.dll", "kernel32")
        .import_lib("dll/ntdll/def/ntdll.spec", "ntdll.dll", "ntdll")
        // The body, import libs and static libs in cmake's link order: the first
        // to define a symbol wins. cmake-built ones are reused until each has a
        // cargo home; `engine:` ones reactos-link builds.
        .link_order(link_order)
        .msvcrtex_crt(MsvcrtexKind::ExeWide)
        .link(ModuleKind::Win32Exe {
            entry: entry.into(),
            subsystem: "windows:5.01".into(),
        });
}
